package com.HG.Forge.Ts.ui.localization

import android.content.Context
import androidx.compose.runtime.Composable
import androidx.compose.runtime.compositionLocalOf
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue

enum class ForgeLanguage { EN, ID }

class ForgeLanguageState(context: Context) {
    private val preferences = context.applicationContext.getSharedPreferences(PREFERENCES, Context.MODE_PRIVATE)
    var language by mutableStateOf(ForgeLanguage.entries.firstOrNull { it.name == preferences.getString(KEY_LANGUAGE, "EN") } ?: ForgeLanguage.EN)
        private set

    fun select(value: ForgeLanguage) {
        if (language == value) return
        language = value
        preferences.edit().putString(KEY_LANGUAGE, value.name).apply()
    }

    private companion object {
        const val PREFERENCES = "forge_language"
        const val KEY_LANGUAGE = "selected_language"
    }
}

val LocalForgeLanguage = compositionLocalOf<ForgeLanguageState> { error("ForgeLanguageState was not provided") }

